{
  "wire_schema": "role_benchmark.player_action",
  "kind": "experiment",
  "portfolio": {
    "hypotheses": [
      {
        "hypothesis_id": "square_root_rate_law",
        "statement": "Peak emf is proportional to the square root of the magnetic flux-change rate, i.e. emf = 20 mV * (N/100)^1 * (A/20)^1 * (field_change/10)^1 * (change_time/100)^-0.5.",
        "confidence": 0.6
      },
      {
        "hypothesis_id": "fractional_rate_minus_third",
        "statement": "Peak emf follows a power law in ramp duration with exponent about -1/3, i.e. emf = 20 mV * (N/100)^1 * (A/20)^1 * (field_change/10)^1 * (change_time/100)^(-1/3).",
        "confidence": 0.4
      }
    ]
  },
  "experiment": {
    "intent": "Refine the change-time exponent by measuring the peak emf at a longer ramp duration; square-root-rate and -1/3-rate laws make distinct predictions.",
    "apparatus": "induction_coil_galvanometer",
    "controls": {
      "coil_turns": 100,
      "loop_area_cm2": 20,
      "field_change_mt": 10,
      "change_time_ms": 400
    },
    "readouts": [
      "peak_emf_mv"
    ],
    "replicates": 1,
    "forecasts": {
      "square_root_rate_law": {
        "peak_emf_mv": 10.0
      },
      "fractional_rate_minus_third": {
        "peak_emf_mv": 12.6
      }
    }
  },
  "final": null
}
